function statisticsArticle(data, now = new Date()) {
  const escape = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const number = (value, integer = false) => new Intl.NumberFormat('ru-RU', {maximumFractionDigits:integer ? 0 : 1}).format(Number(value) || 0);
  const chatId = data.chat_id || data.user_id;
  if (!chatId) throw new Error('Statistics recipient is missing');
  const zone = data.timezone || 'Europe/Moscow';
  const date = data.date || new Intl.DateTimeFormat('en-CA', {timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
  const dateLabel = new Intl.DateTimeFormat('ru-RU', {day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(date + 'T12:00:00Z'));
  const s = data.stats;
  const logs = [...(data.logs || [])].sort((a,b)=>String(a.time || '').localeCompare(String(b.time || '')) || Number(a.id)-Number(b.id));
  const known = logs.filter(row=>row.fiber !== null && row.fiber !== undefined && Number.isFinite(Number(row.fiber)) && Number(row.fiber)>=0 && ['estimated','manual','known','verified'].includes(row.fiber_status));
  const pending = logs.some(row=>['pending','processing'].includes(row.fiber_status));
  const partial = known.length < logs.length;
  const fiberTotal = known.reduce((sum,row)=>sum+Number(row.fiber),0);
  const fiberTarget = Number(data.dailyFiber) > 0 ? Number(data.dailyFiber) : 25;
  const fiberValue = pending ? 'Считаю…' : partial ? (known.length ? '≈ '+number(fiberTotal)+' г · неполные данные' : 'Данные неполные') : '≈ '+number(fiberTotal)+' г';
  const diff = Math.round(s.dailyCalories)-Math.round(s.totalCalories);
  const balance = diff>=0 ? 'Осталось '+number(diff,true)+' ккал' : 'Выше ориентира на '+number(-diff,true)+' ккал';
  const progress = (value,target,kind) => {
    if (!(Number(target)>0)) return '—';
    const ratio=Number(value)/Number(target),filled=kind==='fiber'&&ratio>0?Math.min(4,Math.ceil(ratio*4)):Math.min(4,Math.max(0,Math.floor(ratio*4)));
    // UI thresholds, not a nutritional risk assessment. Fiber is a target, not a ceiling.
    const color=kind==='fiber' ? (ratio>=1?'🟩':ratio>=0.5?'🟨':'🟥') : ratio>1.2?'🟥':ratio>1?'🟨':'🟩';
    return color.repeat(filled)+'⬜'.repeat(4-filled);
  };
  const rows = [
    ['🔥 Калории',number(s.totalCalories,true)+' / '+number(s.dailyCalories,true)+' ккал',progress(s.totalCalories,s.dailyCalories,'calories')+'\n'+(diff>=0?'Ещё '+number(diff,true)+' ккал':'Сверх '+number(-diff,true)+' ккал')],
    ['💪 Белки',number(s.totalProtein)+' / '+number(s.dailyProtein)+' г',progress(s.totalProtein,s.dailyProtein,'protein')],
    ['🥑 Жиры',number(s.totalFats)+' / '+number(s.dailyFats)+' г',progress(s.totalFats,s.dailyFats,'fats')],
    ['🍞 Углеводы',number(s.totalCarbs)+' / '+number(s.dailyCarbs)+' г',progress(s.totalCarbs,s.dailyCarbs,'carbs')],
    ['🌾 Клетчатка',fiberValue.replace(/ г$/,'')+' / '+number(fiberTarget)+' г',pending||partial?'—':progress(fiberTotal,fiberTarget,'fiber')]
  ];
  let html = '<p>📊 <b>Статистика • '+escape(dateLabel)+'</b> 🍴</p><p>&nbsp;</p>';
  const table = items => '<table compact>'+items.map(row=>'<tr>'+row.map(cell=>'<td align="left">'+escape(cell).replace(/\n/g,'<br>')+'</td>').join('')+'</tr>').join('')+'</table>';
  const spacer=['\u00a0','\u00a0','\u00a0'];
  const totals = table([rows[0],spacer,...rows.slice(1,4),spacer,rows[4]]);
  if (!logs.length) html += '<p>Пока ничего не записано. Напиши, что съел — текстом или голосом.</p>';
  else {
    let content='<table compact striped><tr>'+['Время','Продукт','Вес','КБЖУ'].map(label=>'<th align="left">'+label+'</th>').join('')+'</tr>',shown=0;
    for (const row of logs) {
      const item='<tr><td align="left">'+escape(String(row.time||'').slice(0,5))+'</td><td align="left"><b>'+escape(row.item_name)+'</b></td><td align="left">'+number(row.weight)+' г</td><td align="left">'+number(row.calories,true)+' ккал<br>Б '+number(row.protein)+' · Ж '+number(row.fats)+' · У '+number(row.carbs)+'</td></tr>';
      if (shown>=140 || html.length+content.length+item.length+totals.length>27000) break;
      content+=item;shown++;
    }
    html+=content+'</table>';
    if (shown<logs.length) html+='<p>Все записи доступны в дневнике.</p>';
  }
  html+='<p>&nbsp;</p>'+totals;
  const text='Питание · '+dateLabel+'\n'+balance+'\n'+rows.map(row=>row[0]+': '+row[1]+' · '+row[2]).join('\n')+'\n'+logs.map(row=>escape(row.item_name)+' · '+number(row.weight)+' г · '+number(row.calories,true)+' ккал').join('\n');
  return {chat_id:chatId,date,text,rich_html:html,fiber_pending:pending,show_buttons:true};
}
return {json:statisticsArticle($json)};

// Получаем данные через Merge
const allItems = $input.all().flatMap(item => item.json.snapshot ? [{json:item.json.snapshot.profile}, ...item.json.snapshot.logs.map(json=>({json}))] : [item]);

// Разделяем логи и профиль
let logs = [];
let userProfile = {};

allItems.forEach(item => {
  const data = item.json;

  // Если есть item_name — это лог
  if (data.item_name) {
    logs.push(data);
  }
  // Если есть username или daily_calories — это профиль
  else if (data.username || data.daily_calories) {
    userProfile = data;
  }
});

// Суммируем калории за день
let totalCalories = 0;
let totalProtein = 0;
let totalFats = 0;
let totalCarbs = 0;

const nutrient = value => {
  const number = Number(value ?? 0);
  if (!Number.isFinite(number) || number < 0) throw new Error('Некорректные числовые данные в дневнике питания');
  return number;
};
logs = logs.map(log => ({...log, calories:nutrient(log.calories), protein:nutrient(log.protein), fats:nutrient(log.fats), carbs:nutrient(log.carbs)}));
logs.forEach(log => {
  totalCalories += log.calories;
  totalProtein += log.protein;
  totalFats += log.fats;
  totalCarbs += log.carbs;
});

// Получаем цели из профиля
const dailyCalories = userProfile.daily_calories || 2000;
const dailyProtein = userProfile.daily_protein || 150;
const dailyFats = userProfile.daily_fats || 70;
const dailyCarbs = userProfile.daily_carbs || 250;
const goalRu = userProfile.goal_ru || 'поддержание веса';

// Получаем timezone из trigger
const timezone = $('When Executed by Another Workflow').first().json.timezone ?? 'Europe/Moscow';

// Считаем процент и остаток (калории округляем до целых)
const percentage = Math.round((totalCalories / dailyCalories) * 100);
const remaining = Math.max(0, dailyCalories - Math.round(totalCalories));
const over = Math.max(0, Math.round(totalCalories) - dailyCalories);

return {
  json: {
    stats: {
      totalCalories: Math.round(totalCalories),          // Округляем калории до целых
      totalProtein: Number(totalProtein.toFixed(1)),     // Исправлено: строго 1 знак после запятой
      totalFats: Number(totalFats.toFixed(1)),           // Исправлено: строго 1 знак после запятой
      totalCarbs: Number(totalCarbs.toFixed(1)),         // Исправлено: строго 1 знак после запятой
      dailyCalories,
      dailyProtein,
      dailyFats,
      dailyCarbs,
      remaining,
      over,
      percentage
    },
    logs: logs,
    dailyFiber: userProfile.daily_fiber || 25,
    goal_ru: goalRu,
    user_id: userProfile.user_id,
    chat_id: userProfile.user_id || $('When Executed by Another Workflow').first().json.user_id,
    timezone: timezone,
    date: $('When Executed by Another Workflow').first().json.date || null,
    hasRecords: logs.length > 0
  }
};
